#!/bin/bash
# Task 070 -- mesh-sorter: the sort's 43 full-size P4 runs (64 x 65,536 keys) on meshsim v1.2 (WORKER8's sort port,
# meshsim branch v1.2-sort), to compare with task 065's v1.1 runs. The kit (run_p4.sh, kit/: meshsim.jar, the v1.2 tile
# image, jobs.txt, HASHES) is embedded below as a base64 tgz, SHA-256 checked; no other input. Runs run_p4.sh -j 8 in
# /tmp and commits the small outputs (VERDICT, SUMMARY, all.csv, the per-run CSVs and each log's first and last lines);
# full logs stay in /tmp/ms-070/out. Expected 20-30 min, about 28 GB at -j 8 (as 065).
set -u
cd "$(dirname "$0")/.."
RES=$PWD/results/070-meshsorter-v12-p4-full; mkdir -p "$RES"
WANT=99b561250fa4e2df9d61cc9810a4a08bc1609fa7a553f6299c1a0e69e26bf10a
W=/tmp/ms-070; rm -rf "$W"; mkdir -p "$W"
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "$WANT" ] || { echo "kit sha256 mismatch (want $WANT)"; exit 2; }
tar -xzf "$W/kit.tgz" -C "$W" || exit 2
cd "$W/runner" || exit 2
echo "start $(date -u) on $(hostname), $(nproc) threads"; java -version 2>&1 | head -1
./run_p4.sh -j 8 "$W/out"; RC=$?
echo "run_p4.sh exit $RC at $(date -u)"
cp "$W/out/VERDICT.txt" "$W/out/SUMMARY.md" "$W/out/all.csv" "$RES/" 2>/dev/null
mkdir -p "$RES/csv" "$RES/logs"; cp "$W"/out/*.csv "$RES/csv/" 2>/dev/null
for f in "$W"/out/*.log; do [ -f "$f" ] && { head -3 "$f"; echo ...; tail -12 "$f"; } > "$RES/logs/$(basename "$f")"; done
cat "$W/out/VERDICT.txt" 2>/dev/null
exit $RC
